import { access, mkdir, readFile, rename, rm, writeFile } from "node:fs/promises";
import { join } from "node:path";
import type { AvatarJob } from "@img2person/contracts";
import type { JobStore } from "@img2person/pipeline";

export class DiskJobStore implements JobStore {
  readonly #root: string;

  constructor(root: string) {
    this.#root = root;
  }

  #dir(id: string): string {
    return join(this.#root, id);
  }

  async #writeAtomic(path: string, data: Uint8Array | string): Promise<void> {
    const tmp = `${path}.tmp-${crypto.randomUUID()}`;
    await writeFile(tmp, data);
    await rename(tmp, path);
  }

  async create(job: AvatarJob): Promise<void> {
    await mkdir(this.#dir(job.id), { recursive: true });
    await this.#writeAtomic(join(this.#dir(job.id), "job.json"), JSON.stringify(job, null, 2));
  }

  async update(id: string, patch: Partial<AvatarJob>): Promise<void> {
    const job = await this.get(id);
    if (!job) {
      throw new Error(`job ${id} not found`);
    }
    await this.#writeAtomic(
      join(this.#dir(id), "job.json"),
      JSON.stringify({ ...job, ...patch }, null, 2),
    );
  }

  async get(id: string): Promise<AvatarJob | undefined> {
    try {
      const raw = await readFile(join(this.#dir(id), "job.json"), "utf8");
      return JSON.parse(raw) as AvatarJob;
    } catch {
      return undefined;
    }
  }

  async delete(id: string): Promise<void> {
    await rm(this.#dir(id), { recursive: true, force: true });
  }

  async saveImage(id: string, bytes: Uint8Array): Promise<void> {
    await this.#writeAtomic(join(this.#dir(id), "image"), bytes);
  }

  async saveArtifact(id: string, bytes: Uint8Array): Promise<void> {
    await this.#writeAtomic(join(this.#dir(id), "artifact.ply"), bytes);
  }

  async artifactPath(id: string): Promise<string | undefined> {
    const path = join(this.#dir(id), "artifact.ply");
    try {
      await access(path);
      return path;
    } catch {
      return undefined;
    }
  }
}

import { readFile } from "node:fs/promises";
import type { Config } from "@img2person/config";
import { problemDetails, type AvatarJob, type InferenceClient } from "@img2person/contracts";
import { initialStages, runReconstruction } from "@img2person/pipeline";
import { Hono, type Context } from "hono";
import { cors } from "hono/cors";
import type { DiskJobStore } from "./disk-store.js";

export interface AppDeps {
  config: Config;
  store: DiskJobStore;
  inference: InferenceClient;
}

type ErrorStatus = 400 | 404 | 413 | 415;

const ERROR_TITLES: Record<ErrorStatus, string> = {
  400: "Bad Request",
  404: "Not Found",
  413: "Payload Too Large",
  415: "Unsupported Media Type",
};

function problem(c: Context, status: ErrorStatus, detail: string) {
  return c.json(problemDetails(status, ERROR_TITLES[status], detail), status, {
    "content-type": "application/problem+json",
  });
}

export function createApp(deps: AppDeps): Hono {
  const { config, store, inference } = deps;
  const app = new Hono();

  app.use("/*", cors({ origin: config.webOrigin }));

  app.get("/healthz", (c) => c.json({ status: "ok" }));

  app.post("/v1/avatars", async (c) => {
    const body = await c.req.parseBody();
    const file = body["image"];
    if (!(file instanceof File)) {
      return problem(c, 400, "multipart field 'image' is required");
    }
    if (!file.type.startsWith("image/")) {
      return problem(c, 415, `unsupported content type: ${file.type || "unknown"}`);
    }
    if (file.size > config.maxUploadBytes) {
      return problem(c, 413, `image exceeds maximum size of ${config.maxUploadBytes} bytes`);
    }
    const bytes = new Uint8Array(await file.arrayBuffer());
    if (bytes.byteLength === 0) {
      return problem(c, 400, "image is empty");
    }
    if (bytes.byteLength > config.maxUploadBytes) {
      return problem(c, 413, `image exceeds maximum size of ${config.maxUploadBytes} bytes`);
    }

    const id = `av_${crypto.randomUUID()}`;
    const timestamp = new Date().toISOString();
    const job: AvatarJob = {
      id,
      status: "queued",
      stages: initialStages(),
      createdAt: timestamp,
      updatedAt: timestamp,
    };
    await store.create(job);
    await store.saveImage(id, bytes);

    void runReconstruction({
      jobId: id,
      image: { data: bytes, contentType: file.type, filename: file.name || "image" },
      maxUploadBytes: config.maxUploadBytes,
      inference,
      store,
    });

    return c.json({ id, status: "queued" }, 202);
  });

  app.get("/v1/avatars/:id", async (c) => {
    const id = c.req.param("id");
    const job = await store.get(id);
    if (!job) {
      return problem(c, 404, `avatar ${id} not found`);
    }
    return c.json(job);
  });

  app.get("/v1/avatars/:id/artifact", async (c) => {
    const id = c.req.param("id");
    const job = await store.get(id);
    const path = await store.artifactPath(id);
    if (!job || job.status !== "complete" || !path) {
      return problem(c, 404, `artifact for avatar ${id} not found`);
    }
    const bytes = await readFile(path);
    return c.body(new Uint8Array(bytes), 200, {
      "content-type": "application/octet-stream",
      "content-disposition": `attachment; filename="avatar-${id}.ply"`,
    });
  });

  app.delete("/v1/avatars/:id", async (c) => {
    const id = c.req.param("id");
    const job = await store.get(id);
    if (!job) {
      return problem(c, 404, `avatar ${id} not found`);
    }
    await store.delete(id);
    return c.body(null, 204);
  });

  return app;
}

import { mkdir } from "node:fs/promises";
import { serve } from "@hono/node-server";
import { loadConfig } from "@img2person/config";
import { HttpInferenceClient } from "@img2person/contracts";
import { createApp } from "./app.js";
import { DiskJobStore } from "./disk-store.js";

const config = loadConfig(process.env);
await mkdir(config.storageDir, { recursive: true });

const store = new DiskJobStore(config.storageDir);
const inference = new HttpInferenceClient(config.inferenceUrl);
const app = createApp({ config, store, inference });

serve({ fetch: app.fetch, port: config.apiPort }, (info) => {
  console.log(`img2person api listening on http://localhost:${info.port}`);
});

import { type AvatarJob, type ProblemDetails } from "@img2person/contracts";

export const MAX_UPLOAD_BYTES = 10 * 1024 * 1024;

export class ApiError extends Error {
  readonly status: number;
  readonly detail: string;

  constructor(problem: ProblemDetails) {
    super(problem.detail ?? problem.title);
    this.name = "ApiError";
    this.status = problem.status;
    this.detail = problem.detail ?? problem.title;
  }
}

async function readProblem(response: Response): Promise<ProblemDetails> {
  try {
    const body = (await response.json()) as Partial<ProblemDetails>;
    if (typeof body.title === "string" && typeof body.status === "number") {
      return {
        type: body.type ?? "about:blank",
        title: body.title,
        status: body.status,
        detail: body.detail,
      };
    }
  } catch {
    // fall through to the generic problem below
  }
  return {
    type: "about:blank",
    title: response.statusText || "Request failed",
    status: response.status,
  };
}

export async function uploadAvatar(image: File): Promise<{ id: string; status: string }> {
  const form = new FormData();
  form.append("image", image);
  const response = await fetch("/v1/avatars", { method: "POST", body: form });
  if (!response.ok) {
    throw new ApiError(await readProblem(response));
  }
  return (await response.json()) as { id: string; status: string };
}

export async function fetchAvatar(id: string): Promise<AvatarJob> {
  const response = await fetch(`/v1/avatars/${id}`);
  if (!response.ok) {
    throw new ApiError(await readProblem(response));
  }
  return (await response.json()) as AvatarJob;
}

export async function deleteAvatar(id: string): Promise<void> {
  const response = await fetch(`/v1/avatars/${id}`, { method: "DELETE" });
  if (!response.ok && response.status !== 404) {
    throw new ApiError(await readProblem(response));
  }
}

